import re
user_texts=[]
for it in items:
 if it.get('type')=='message' and it['message'].get('role')=='user':
  user_texts.append(''.join(x.get('text','') for x in it['message'].get('content',[])))
def parse_grid(s, label):
 m=re.search(rf'{label} \((\d+)x(\d+)\):\n', s)
 if not m: raise ValueError(label)
 h,w=map(int,m.groups()); rows=[]; tail=s[m.end():]
 for line in tail.splitlines()[:h]:
  rows.append(list(map(int,line.split())))
 assert len(rows)==h and all(len(r)==w for r in rows), (label,h,w,[len(r) for r in rows])
 return rows
pairs=[]
for t in user_texts:
 if 'Demo pair' in t:
  ix=parse_grid(t,'Demo pair 1 input') if 'Demo pair 1 input' in t else None
  if ix is not None:
   pairs.append((ix,parse_grid(t,'Demo pair 1 output')))
  else:
   pairs.append((parse_grid(t,'Demo pair 2 input'),parse_grid(t,'Demo pair 2 output')))
print([(len(a),len(a[0]),len(b),len(b[0])) for a,b in pairs])

def comps(grid):
 h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row),key=lambda v:sum(row.count(v) for row in grid))
 seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==bg or (r,c) in seen: continue
   val=grid[r][c]; q=[(r,c)];seen.add((r,c));
   for y,x in q:
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==val:
      seen.add((yy,xx));q.append((yy,xx))
   cs.append((val,len(q),min(y for y,x in q),max(y for y,x in q),min(x for y,x in q),max(x for y,x in q),q))
 return bg,sorted(cs,key=lambda z:-z[1])
for i,(a,b) in enumerate(pairs):
 bg,cs=comps(a); print(i,bg,[(c[:6]) for c in cs[:8]])

def comps_occupied(grid,bg):
 h,w=len(grid),len(grid[0]); seen=set(); cs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c))
   for y,x in q:
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]!=bg:
      seen.add((yy,xx));q.append((yy,xx))
   cs.append(q)
 return sorted(cs,key=len,reverse=True)
for i,(a,b) in enumerate(pairs):
 bg=max(set(x for row in a for x in row),key=lambda v:sum(row.count(v) for row in a)); cc=comps_occupied(a,bg)
 print(i,bg,[(len(c),(min(y for y,x in c),max(y for y,x in c),min(x for y,x in c),max(x for y,x in c))) for c in cc[:5]])
